"""Perfil local agregado: não imprime nem transmite valores de células."""
from __future__ import annotations
import hashlib, json, os
from pathlib import Path
import pandas as pd
ROOT=Path(__file__).resolve().parents[1]; OUT=ROOT/"artifacts/data_assessment"; SOURCE=Path(os.getenv("CANDIDATES_ROOT",r"C:\Users\Yuri\rt_data\genericos"))
def profile_xlsx(path: Path):
    frame=pd.read_excel(path,engine="openpyxl")
    return {"file":path.name,"format":"xlsx","records":int(len(frame)),"columns":[{"name":str(c),"type":str(t),"missing":int(frame[c].isna().sum())} for c,t in frame.dtypes.items()],"duplicate_full_rows":int(frame.duplicated().sum())}
def write_profile(name,data): (OUT/"profiles"/f"{name}.json").write_text(json.dumps(data,ensure_ascii=False,indent=2),encoding="utf-8")
def main():
    (OUT/"profiles").mkdir(parents=True,exist_ok=True)
    files=list(SOURCE.glob("*")); xlsx=sorted(SOURCE.glob("*.xlsx")); csvs=sorted(SOURCE.glob("*.csv")); commercial_files=[x for x in xlsx if x.name.startswith(("d","f"))]
    commercial={"candidate":"commercial","classification":"USE_WITH_TRANSFORMATIONS","authorization":"confirmed by project owner on 2026-09-26","formats":["xlsx","pbix","csv fragments"],"tables":len(commercial_files),"profiles":[profile_xlsx(x) for x in commercial_files],"relationships_inferred":["orders.customer_id -> customers.customer_id","orders.representative_id -> representatives.representative_id","order_items.order_id -> orders.order_id","order_items.product_id -> products.product_id","products subgroup/group/collection/line dimensions","targets.representative_id -> representatives.representative_id"],"quality":{"referential_integrity":"deferred to strict FK validation in PostgreSQL setup; load aborts on violations","related_entities":11,"contains_dates":True,"contains_status":True,"contains_monetary_values":True,"derived_indicators":["order value","item value","discount rate","sales by issue period","representative achieved amount"],"temporal_ambiguities":["issue versus expected-delivery date","customer registration versus sales date","collection validity versus target date"],"aggregation_risks":["orders to order_items 1:N duplicates header amount","targets must be aggregated before joining items"]},"risk":"deidentified fields and names are never sent as row values to external providers; source is read-only","transformations":["normalize 11 XLSX tables to PostgreSQL","add PK/FK/indexes","freeze SHA-256 manifest","disable model result samples"]}
    financial_files=sorted((SOURCE/"financeiro").glob("*.xlsx"))
    financial={"candidate":"financeiro","classification":"DO_NOT_USE","formats":["xlsx","pbix"],"tables":len(financial_files),"profiles":[profile_xlsx(x) for x in financial_files],"risk":"authorization and privacy assessment unresolved; names of companies/suppliers and proprietary financial records may be identifying","reproducibility":"requires semantic reconstruction and partition consolidation"}
    fragments={"candidate":"csv_synthetic_fragments","classification":"DO_NOT_USE","formats":["csv"],"files":len(csvs),"records":sum(max(0,sum(1 for _ in x.open(encoding="utf-8-sig"))-1) for x in csvs),"risk":"fragmented derivative files do not constitute a coherent relational snapshot","reproducibility":"no declared keys, DDL, or reliable source-to-table mapping"}
    for n,d in [("commercial",commercial),("financeiro",financial),("csv_synthetic_fragments",fragments)]: write_profile(n,d)
    recommendation={"selected_dataset":"commercial","classification":"USE_WITH_TRANSFORMATIONS","reason":"authorized deidentified commercial source with 11 related entities, dates, statuses, monetary measures and aggregation/temporal ambiguities; normalized locally without sending rows externally","alternatives":{"financeiro":"DO_NOT_USE","csv_synthetic_fragments":"DO_NOT_USE","synthetic_commercial":"available for tests"},"source_root_hash":hashlib.sha256("\n".join(f"{x.name}:{x.stat().st_size}" for x in sorted(files)).encode()).hexdigest()}
    (OUT/"recommendation.json").write_text(json.dumps(recommendation,ensure_ascii=False,indent=2),encoding="utf-8")
    lines=["# Avaliação das bases candidatas","","Avaliação feita localmente, por estrutura e estatísticas agregadas; nenhum valor de linha foi exposto.","","| Base | Classificação | Justificativa |","|---|---|---|", "| comercial | USE_WITH_TRANSFORMATIONS | Autorização confirmada; 11 tabelas relacionadas, normalização XLSX→PostgreSQL necessária. |", "| financeiro | DO_NOT_USE | Autorização específica e privacidade não confirmadas. |", "| CSVs sintéticos fragmentados | DO_NOT_USE | Não formam snapshot relacional íntegro. |","","## Comercial","",f"Foram identificadas {len(commercial_files)} planilhas: dimensões de clientes, produtos, classificação de produtos e representantes; fatos de pedidos, itens e metas. Há datas, status e medidas monetárias. Relações são inferidas e passam a ser FKs no schema preparado. Risco analítico central: `orders` → `order_items` é 1:N e duplica medidas de cabeçalho quando agregado após o join. As datas de emissão, entrega prevista, cadastro, vigência de coleção e meta têm semânticas distintas.","","O campo de identificação descaracterizado e nomes não são enviados a modelos externos; a amostra de resultados para o agente é desabilitada no dataset.","","Os perfis completos (somente contagens, cabeçalhos, tipos, nulos e duplicidades) estão em `profiles/`."]
    (OUT/"report.md").write_text("\n".join(lines)+"\n",encoding="utf-8")
    print("Assessment written to artifacts/data_assessment")
if __name__=="__main__": main()
